"""Assemble toing-research.md from parts and appendices, then run the checks."""
import io, re, collections, pathlib
HERE = pathlib.Path(__file__).parent
P = HERE / "parts"
rd = lambda f: io.open(P / f, encoding="utf-8").read().strip() + "\n\n"
head = """# Toing: Swiggy's ₹99 Problem

**A Board recommendation on Toing: keep it, but stop paying for ₹99 trips**

Team: Harsh Kawatra (Delhi Technological University) · Gursimran Kaur (GGSIPU) · Dayita Arora
(Ramjas College, University of Delhi)

Prepared for: NSBC, Consilium'26, NSUT, September 2026

---

"""
body = rd("part-A.md") + rd("part-B.md") + rd("part-C.md") + rd("part-D-full.md")
ACC = "(Accessed: 29 September 2026)"
S = [("S01", "Swiggy Limited (2026) Q1 FY27 shareholder letter. Available at: https://www.swiggy.com/corporate/ " + ACC),
     ("S02", "Inc42 (2026) Swiggy's money map: the verticals built around the food delivery core. Available at: https://inc42.com/features/swiggys-money-map-the-verticals-built-around-food-delivery-core/ " + ACC),
     ("S03", "MediaNama (2025) Toing app: Swiggy's budget meals cost more after platform fees, GST. Available at: https://www.medianama.com/2025/09/223-toing-app-swiggy-save-money-on-meals/ " + ACC),
     ("S04", "MediaNama (2026) Swiggy says zero-commission food delivery is unsustainable, bets on Toing to grow the market. Available at: https://www.medianama.com/2026/08/223-swiggy-earnings-call-key-takeaways/ " + ACC),
     ("S05", "Storyboard18 (2026) Swiggy's Toing user base closes in on Zomato, reaches 33 million weekly users: CLSA. Available at: https://www.storyboard18.com/brand-marketing/swiggys-toing-user-base-closes-in-on-zomato-reaches-33-million-weekly-users-clsa-ws-o-110238.htm " + ACC),
     ("S06", "MediaNama (2026) Eternal tests Zomato Now food vending pods in Gurugram offices. Available at: https://www.medianama.com/2026/08/223-eternal-food-delivery-zomato-now/ " + ACC),
     ("S07", "Entrackr (2026) Swiggy shuts down 15-min food delivery app Snacc; MediaNama (2026) Swiggy shuts down SNACC. Available at: https://entrackr.com/news/swiggy-shuts-down-15-min-food-delivery-app-snacc-11133594 " + ACC),
     ("S08", "MediaNama (2026) Rapido rolls out Ownly in Bengaluru with zero-commission model; Business Today (2026) Rapido's Ownly goes live within the main app. Available at: https://www.medianama.com/2026/03/223-rapido-ownly-bengaluru-zero-commission-model-sustain-without-charging-restaurants/ " + ACC),
     ("S09", "Deccan Herald (2026) Gig workers welfare fee: Karnataka notifies 1% levy on aggregators. Available at: https://www.deccanherald.com/india/karnataka/swiggy-zomato-to-pay-welfare-fee-to-gig-workers-as-karnataka-notifies-1-levy-on-aggregators-3900681 " + ACC),
     ("S10", "Inc42 (2025) Zomato, Swiggy deliveries to get costlier with new 18% GST; Angel One (2025) 18% GST on e-commerce delivery from 22 Sep. Available at: https://inc42.com/buzz/zomato-swiggy-deliveries-to-get-costlier-with-new-18-gst/ " + ACC),
     ("S11", "Delivery-partner pay guides (2026) Swiggy delivery partner earnings, base pay and distance pay. Secondary source, snippet only " + ACC),
     ("S12", "Restaurant commission guides (2026) Zomato and Swiggy commission rates. Secondary source, snippet only " + ACC),
     ("S13", "IIFL (2022) To cut costs, Dunzo encouraging users to choose the 60-minute delivery option. Available at: https://www.indiainfoline.com/news/markets/to-cut-costs-dunzo-encouraging-users-to-choose-the-60-minute-delivery-option " + ACC),
     ("S14", "Eternal Limited (2026) Q1 FY27 results. Secondary summaries, snippet only " + ACC),
     ("S15", "Morwitz, V., Steckel, J. and Gupta, S. (2007) When do purchase intentions predict sales? International Journal of Forecasting, 23(3), pp. 347 to 364.")]
app = "## Appendix A: Bibliography\n\n" + "\n".join(f"- **{i}** {s}" for i, s in S) + "\n\n"
tb = io.open(HERE.parent / "model" / "model_tables.md", encoding="utf-8").read().split("\n", 1)[1]
tb = re.sub(r"^## ", "### ", tb, flags=re.M)
app += "## Appendix B: Model tables\n\nGenerated by `model/toing_model.py` and `model/make_tables.py` on 29 September 2026.\n" + tb + "\n"
src = io.open(HERE.parent / "model" / "toing_model.py", encoding="utf-8").read()
rows = []
for line in src.splitlines():
    code, _, com = line.partition("#")
    m = re.match(r"\s*(A\d+(?: to A\d+)?)\s+(.*)$", com)
    if m and "=" in code:
        names = ", ".join(re.findall(r"([A-Z_0-9]+)=", code))
        rows.append((m.group(1), names, m.group(2).strip().replace("|", "/")))
app += ("## Appendix C: Assumption register\n\nIDs and bases as commented in `model/toing_model.py`. A15 stands for the GST rates and A16 for the Karnataka fee cap, "
        "which are public inputs shown in the model header.\n\n| ID | Inputs | Basis |\n|---|---|---|\n" + "\n".join(f"| {a} | {b} | {c} |" for a, b, c in rows) + "\n\n")
gl = [("AOV", "Average order value: gross order value divided by completed orders"), ("GOV", "Gross order value: value of completed orders including fees, taxes and packaging, before discounts"),
      ("Contribution margin", "Revenue less variable costs of an order, before overheads"), ("Adjusted EBITDA", "Earnings before interest, tax, depreciation and amortisation, adjusted as Swiggy defines it"),
      ("Take rate", "Swiggy revenue as a share of GOV"), ("Toing", "Swiggy's standalone app for meals from ₹49 to ₹150, launched August 2025"),
      ("Snacc", "Swiggy's 10 to 15-minute snacks app, launched January 2025, shut February 2026"), ("Drop", "A pickup point (hostel gate, PG lobby, office desk) served by a pooled rider run"),
      ("Run", "One rider trip that collects several meals for one Drop"), ("Slot batching", "Grouping two door orders into one trip inside a delivery window"),
      ("Door fee", "Fee charged when a Toing order is delivered to the door instead of a Drop"), ("Toing Pass", "Proposed ₹49 a month subscription for free Drop delivery"),
      ("CAC", "Customer acquisition cost: spend to acquire one new transacting user"), ("LTV", "Lifetime value: contribution a user generates over a horizon"),
      ("Migration", "A Toing user who begins placing ₹700-type orders on the core app"), ("Trade-down", "A core-app order replaced by a cheaper Toing order"),
      ("Incremental share", "Share of Toing users who are new to Swiggy or dormant"), ("CoSS", "Code on Social Security, 2020, in force 21 November 2025"),
      ("Platform Innovations", "Swiggy's segment that houses Toing and other early-stage products"), ("MTU", "Monthly transacting users"), ("WAU", "Weekly active users"),
      ("EDLP", "Everyday low price: fixed low prices in place of coupons"), ("NOV", "Net order value: gross order value less discounts"), ("Instamart", "Swiggy's quick-commerce business"),
      ("Eternal", "Formerly Zomato, the market leader in food delivery"), ("Rapido Ownly", "Rapido's zero-commission food delivery service"),
      ("Bolt", "Swiggy's faster food delivery proposition inside the core app"), ("99 Store", "Swiggy's flat-price value offer inside the core app"),
      ("Flip point", "Value of one input at which the rebuild and a shutdown have equal three-year results"), ("Gate", "A pre-set metric threshold at which the Board continues or shuts Toing"),
      ("Tornado", "Chart ranking inputs by the swing they cause in a result"), ("Kill, Scale, Funnel, Rebuild", "The four paths compared: shut Toing; grow it as it runs; run it as an acquisition funnel; rebuild it around the trip")]
app += "## Appendix D: Glossary\n\n| Term | Meaning |\n|---|---|\n" + "\n".join(f"| {a} | {b} |" for a, b in gl) + "\n\n"
app += """## Appendix E: Data conflicts and resolutions

| Topic | Conflict | Resolution |
|---|---|---|
| Core AOV | Case says about ₹700; Q1 FY27 figures imply about ₹500 | Case figure used on slides; conclusion tested at ₹500 (EBITDA ₹15.5 an order) |
| Toing footprint | Case: starting in Pune; Swiggy letter: about 50 cities | Case framing kept for the order economics; public scale cited as public |
| Toing loss split | Swiggy: spend "largely" on acquisition; our triangulation: two-thirds per-order | Shown as an estimate with a sensitivity grid in section 6 |
| Eternal margin basis | Eternal reports adjusted EBITDA on NOV (5.6%), Swiggy on GOV (3.1%) | Not compared directly; noted in section 13 |
| CAC | Analyst ranges ₹400 to ₹500 (Swiggy); snippet-only sources | Tested across ₹400 to ₹1,200; conclusion unchanged |
"""
doc = head + body + app
io.open(HERE / "toing-research.md", "w", encoding="utf-8").write(doc)
h = [l for l in doc.splitlines() if l.startswith("## ")]
dup = [k for k, v in collections.Counter(h).items() if v > 1]
cited = {f"S{n}" for n in re.findall(r"S(\d{2})\b", body)}
bad = ["delve", "landscape", "unlock", "game-changer", "here's", "let's", "bottom line", "it's not just", "make no mistake", "in today's", "fast-paced", "seamless", "robust",
       "tapestry", "testament", "realm", "holistic", "synergy", "paradigm", "cutting-edge", "revolutioniz", "crucial", "pivotal", "furthermore", "moreover", "in conclusion",
       "it is worth noting", "navigate the"]
print("words", len(doc.split()), "dashes", doc.count("—") + doc.count("–"), "dup headings", dup)
print("banned", {b: len(re.findall(re.escape(b), doc, re.I)) for b in bad if re.search(re.escape(b), doc, re.I)})
print("cited but not in bibliography", sorted(c for c in cited if c not in {i for i, _ in S}))
print("headings", len(h), "assumption rows", len(rows), "tables", doc.count("\n|---") )
print([x for x in h][:60])
